function openRecord(r){const locked=SteuerraumFeatures.closedYear(data,r.date.slice(0,4));current=structuredClone(r);draftLinks=structuredClone(r.links||[]);const form=$('#recordForm');form.elements.id.value=r.id;form.elements.date.value=r.date;form.elements.amount.value=(r.amount/100).toFixed(2);form.elements.company.value=r.company||'';form.elements.description.value=r.description;form.elements.category.innerHTML=cats().map(c=>'<option>'+esc(c)+'</option>').join('');form.elements.category.value=r.category;form.elements.type.value=r.type||'';$('#flag').textContent=r.flag?'У вихідній таблиці дата позначена червоним. Причину ще не уточнено.':'';$('#linkName').value='';$('#linkUrl').value='';renderLinks();document.querySelectorAll('#recordForm input,#recordForm select,#recordForm textarea').forEach(el=>el.disabled=locked);$('#recordSave').hidden=locked;$('#recordDelete').hidden=locked||!data.records.some(x=>x.id===r.id);$('#recordDuplicate').hidden=locked||!data.records.some(x=>x.id===r.id);$('#addLink').hidden=locked;$('#recordReadOnly').textContent=locked?'Рік закритий: лише перегляд і завантаження документів.':r.duplicateOf&&!data.records.some(x=>x.id===r.id)?'Нова копія з тим самим чеком. Зміни суму та статтю витрат і натисни «Зберегти витрату».':'';$('#detail').showModal();}
