$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Файл завеликий: максимум 20 МБ');const incoming=validate(JSON.parse(await file.text()));const map=new Map(data.records.map(r=>[r.id,r]));for(const r of incoming.records){const old=map.get(r.id);if(old){if(JSON.stringify({...old,links:[]})!==JSON.stringify({...r,links:[]}))throw Error('Операція '+r.id+' відрізняється від збереженої. Імпорт зупинено, щоб не перезаписати зміни.');r.links=[...(old.links||[]),...r.links.filter(l=>!old.links?.some(o=>o.url===l.url))];}map.set(r.id,r);}const categories=new Map(data.categories.map(c=>[c.name,c]));incoming.categories.forEach(c=>categories.set(c.name,c));const tripMap=new Map((data.trips||[]).map(t=>[t.id,t]));for(const t of incoming.trips||[]){if(tripMap.has(t.id)&&JSON.stringify(tripMap.get(t.id))!==JSON.stringify(t))throw Error('Конфлікт імпорту поїздки '+t.id);tripMap.set(t.id,t);}const mergedAnnual={...(data.annualDetails||{})};for(const [yr,entry] of Object.entries(incoming.annualDetails||{})){if(mergedAnnual[yr]&&JSON.stringify(mergedAnnual[yr])!==JSON.stringify(entry))throw Error('Конфлікт додаткових даних року '+yr);mergedAnnual[yr]=entry;}const bankMap=new Map((data.bankImports||[]).map(entry=>[entry.id,entry]));for(const entry of incoming.bankImports||[]){if(bankMap.has(entry.id)&&JSON.stringify(bankMap.get(entry.id))!==JSON.stringify(entry))throw Error('Конфлікт історії банківської виписки');bankMap.set(entry.id,entry);}const incomeMap=new Map((data.incomeRecords||[]).map(r=>[r.id,r]));for(const r of incoming.incomeRecords||[]){if(incomeMap.has(r.id)&&JSON.stringify(incomeMap.get(r.id))!==JSON.stringify(r))throw Error('Конфлікт імпорту доходу '+r.id);incomeMap.set(r.id,r);}const payments={};for(const key of ['insuranceRecords','taxPaymentRecords']){const entries=new Map((data[key]||[]).map(r=>[r.id,r]));for(const r of incoming[key]||[]){if(entries.has(r.id)&&JSON.stringify(entries.get(r.id))!==JSON.stringify(r))throw Error('Конфлікт імпорту платежу '+r.id);entries.set(r.id,r);}payments[key]=[...entries.values()];}const mergedRecords=[...map.values()];const mergedTrips=SteuerraumFeatures.validateTrips([...tripMap.values()],mergedRecords);if(persist({...data,records:mergedRecords,categories:[...categories.values()],trips:mergedTrips,closedYears:{...(incoming.closedYears||{}),...(data.closedYears||{})},annualDetails:mergedAnnual,bankImports:[...bankMap.values()],incomeRecords:[...incomeMap.values()],...payments,bankExclusions:{...(incoming.bankExclusions||{}),...(data.bankExclusions||{})}})){if(incoming.records.length)year=incoming.records[0].date.slice(0,4);render();message('Імпортовано '+incoming.records.length+' операцій. Дані не надсилалися в GitHub.');}}catch(err){message('Імпорт не виконано: '+err.message,true);}e.target.value='';};
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
