$('#csv').onclick=()=>{if(tab==='insurance'||tab==='taxes'){const type=tab==='insurance'?'insurance':'tax';download('Steuerraum-'+type+'-'+year+'.csv',SteuerraumFeatures.paymentCsv(data,type,year,filteredPayments(type)),'text/csv;charset=utf-8');return;}if(tab==='income'){download('Steuerraum-Einnahmen-'+year+'.csv',SteuerraumFeatures.incomeCsv(data,year,filteredIncome()),'text/csv;charset=utf-8');return;}if(tab==='overview'){download('Steuerraum-Jahresuebersicht-'+year+'.csv',SteuerraumFeatures.annualSummaryCsv(data,year),'text/csv;charset=utf-8');return;}if(tab==='travel'){exportTravel();return;}const rows=[['Datum','Betrag EUR','Kostenart','Verwendungszweck','Firma','Rechnung','Dokumente'],...filtered().map(r=>[r.date,(r.amount/100).toFixed(2),r.category,r.description,r.company,r.type,(r.links||[]).map(l=>l.url).join(' ')])];download('Steuerraum-'+year+'.csv','\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');};

function travelCheckbox(r){const locked=SteuerraumFeatures.closedYear(data,r.date.slice(0,4));return '<label class="travelChoice"><input type="checkbox" data-travel-select="'+esc(r.id)+'" '+(locked?'disabled ':'')+(SteuerraumFeatures.travelSelected(r,data.trips||[])?'checked':'')+'> Для таблиці подорожей</label>';}
function bindTravelSelection(){document.querySelectorAll('[data-travel-select]').forEach(box=>{box.onclick=e=>e.stopPropagation();box.onchange=()=>{const next=SteuerraumFeatures.setTravelSelection(data,box.dataset.travelSelect,box.checked);if(persist(next)){render();message(box.checked?'Витрату відібрано. Вона доступна у вкладці подорожей для розподілу.':'Витрату прибрано з таблиці подорожей. Операція та документи залишилися у реєстрі.');}else box.checked=!box.checked;};});}
const monthLabels=['Січень','Лютий','Березень','Квітень','Травень','Червень','Липень','Серпень','Вересень','Жовтень','Листопад','Грудень'];
function displayDate(d){return d.split('-').reverse().join('.');}

const documentExpansion=new Map();
function rememberDocumentExpansion(){document.querySelectorAll('[data-doc-group]').forEach(el=>{if(el.dataset.docSearch!=='true')documentExpansion.set(el.dataset.docGroup,el.open);});}
function renderDocuments(){
rememberDocumentExpansion();
$('#view').innerHTML='<section class="panel documentArchive"><div class="panelhead"><div><h2>Документи</h2></div></div><div class="filters"><input type="search" id="docSearch" aria-label="Пошук документів" placeholder="Компанія, дата або назва…"></div><div id="docGroups"></div></section>';
const update=()=>{rememberDocumentExpansion();const q=$('#docSearch').value.toLowerCase().trim();const groups=SteuerraumFeatures.documentGroups(data.records).map(y=>({...y,months:y.months.map(m=>({...m,documents:m.documents.filter(d=>!q||[d.name,d.date,displayDate(d.date),...d.records.flatMap(r=>[r.description,r.company,r.date,displayDate(r.date)])].join(' ').toLowerCase().includes(q))})).filter(m=>m.documents.length)})).filter(y=>y.months.length);
const expanded=(key,fallback=false)=>(q||documentExpansion.get(key)===true||(!documentExpansion.has(key)&&fallback))?'open':'';
const row=d=>{const companies=[...new Set(d.records.map(r=>(r.company||'').split(',')[0].trim()).filter(Boolean))].join(', ')||'Документ';return '<div class="documentLine"><time class="documentDate" datetime="'+esc(d.date)+'" title="'+(d.dateSource==='document'?'Дата документа':'Дата операції')+'">'+esc(displayDate(d.date))+'</time><span class="documentCompany" title="'+esc(companies)+'">'+esc(companies)+'</span><div class="documentAmounts">'+d.records.map(r=>'<span class="documentAmount">'+esc(money(r.amount))+'</span>').join('')+'</div><div class="documentActions"><a class="documentPdf" href="'+esc(safeUrl(d.url))+'" target="_blank" rel="noopener noreferrer" title="'+esc(d.name)+'" aria-label="'+esc('Відкрити '+d.name)+'">'+(/\.pdf$/i.test(d.name)?'PDF':'Файл')+' ↗</a></div></div>';};
$('#docGroups').innerHTML=groups.length?groups.map(y=>{const count=y.months.reduce((s,m)=>s+m.documents.length,0),key='year-'+y.year;return '<details class="documentYear" data-doc-group="'+esc(key)+'" data-doc-search="'+!!q+'" '+expanded(key,y.year===year)+'><summary><span>▱ '+esc(y.year)+'</span><small>'+count+' документів</small></summary>'+y.months.map(m=>{const monthKey=y.year+'-'+m.month;return '<details class="documentMonth" data-doc-group="'+esc(monthKey)+'" data-doc-search="'+!!q+'" '+expanded(monthKey)+'><summary><span>'+esc(m.month+' — '+monthLabels[Number(m.month)-1])+'</span><small>'+m.documents.length+' документів</small></summary>'+m.documents.map(row).join('')+'</details>';}).join('')+'</details>';}).join(''):'<div class="empty"><h2>Документів не знайдено</h2></div>';
};$('#docSearch').oninput=update;update();
}

function travelAmount(ids,label){const rows=travelCostRecords(ids),total=rows.reduce((s,r)=>s+r.amount,0);if(!rows.length)return '';return '<button type="button" class="travelAmount" data-travel-amount="'+esc(JSON.stringify(rows.map(r=>r.id)))+'" aria-label="'+esc(label+': '+money(total)+' · показати транзакції')+'">'+money(total)+'</button>';}
function travelCostRecords(ids){const selected=new Set(ids);return data.records.filter(r=>selected.has(r.id)&&r.travelIncluded!==false).sort((a,b)=>a.date.localeCompare(b.date));}
function openTravelCosts(ids){const rows=travelCostRecords(ids);if(rows.length===1){openRecord(rows[0]);return;}if(!rows.length)return;$('#travelCostSummary').textContent=rows.length+' транзакцій · '+money(rows.reduce((s,r)=>s+r.amount,0));$('#travelCostRows').innerHTML=rows.map(r=>'<button type="button" class="travelCostRow" data-open-cost="'+esc(r.id)+'"><span><b>'+esc(displayDate(r.date))+' · '+esc(r.company||r.category)+'</b><small>'+esc(r.description)+'</small><small>Документів: '+(r.links||[]).length+'</small></span><strong>'+money(r.amount)+' ↗</strong></button>').join('');document.querySelectorAll('[data-open-cost]').forEach(b=>b.onclick=()=>{const r=data.records.find(r=>r.id===b.dataset.openCost);if(r){$('#travelCostDetail').close();openRecord(r);}});$('#travelCostDetail').showModal();}
$('#travelCostClose').onclick=()=>$('#travelCostDetail').close();

function renderTravel(){
const summary=SteuerraumFeatures.travelSummary(data.trips||[],data.records,year),totals=summary.totals;const costIds=type=>summary.trips.flatMap(t=>type?t.costs[type]:SteuerraumFeatures.costTypes.flatMap(k=>t.costs[k]));
$('#view').innerHTML='<div class="stats travelStats"><div class="stat"><span>Квитки · Tickets</span><b>'+(travelAmount(costIds('tickets'),'tickets')||money(0))+'</b></div><div class="stat"><span>Проживання · Accommodation</span><b>'+(travelAmount(costIds('accommodation'),'accommodation')||money(0))+'</b></div><div class="stat"><span>Інше · Other</span><b>'+(travelAmount(costIds('other'),'other')||money(0))+'</b></div></div><section class="panel travelPanel"><div class="panelhead"><div><h2>Reisekosten · '+esc(year)+'</h2><p class="travelHelp">Суми розраховані з прив’язаних операцій реєстру. Таблиця поїздок не створює повторних витрат.</p></div></div><div class="travelToolbar actions"><button id="travelCsv">↓ Експорт для бухгалтера · CSV</button><button id="travelPrint">Друк / PDF</button></div><div class="printTitle">Reisekosten · '+esc(year)+'</div><div class="tablewrap"><table class="travelTable"><thead><tr><th colspan="2" class="travelDates">Reisedaten</th><th rowspan="2">Tickets, EUR</th><th rowspan="2">Accommodation, EUR</th><th rowspan="2">Other, EUR</th><th rowspan="2">Reiseziel</th><th rowspan="2">Zweck der Reise</th><th rowspan="2" class="no-print">Дії</th></tr><tr><th>von</th><th>bis</th></tr></thead><tbody>'+summary.trips.map(t=>{const sums=SteuerraumFeatures.tripTotals(t,data.records);return '<tr><td>'+esc(displayDate(t.start))+'</td><td>'+esc(displayDate(t.end))+'</td><td class="amount">'+travelAmount(t.costs.tickets,t.destination+' · tickets')+'</td><td class="amount">'+travelAmount(t.costs.accommodation,t.destination+' · accommodation')+'</td><td class="amount">'+travelAmount(t.costs.other,t.destination+' · other')+'</td><td>'+esc(t.destination)+'</td><td class="tripPurpose">'+esc(t.purpose)+'</td><td class="no-print"><button data-trip="'+esc(t.id)+'" '+(SteuerraumFeatures.closedYear(data,year)?'disabled':'')+'>Редагувати</button></td></tr>';}).join('')+'</tbody><tfoot><tr><td colspan="2">Summe</td><td class="amount">'+(travelAmount(costIds('tickets'),'tickets')||money(0))+'</td><td class="amount">'+(travelAmount(costIds('accommodation'),'accommodation')||money(0))+'</td><td class="amount">'+(travelAmount(costIds('other'),'other')||money(0))+'</td><td colspan="2">Gesamtkosten: <strong>'+(travelAmount(costIds(),'Усі витрати на подорожі')||money(0))+'</strong></td><td class="no-print"></td></tr></tfoot></table></div>'+(!summary.trips.length?'<div class="empty">Поїздки за цей рік ще не додані. Натисніть «Додати поїздку».</div>':'')+'<div class="travelReconciliation '+(summary.difference||summary.unassigned.length||summary.otherCategory.length?'needsReview':'')+'"><b>'+(summary.difference||summary.unassigned.length||summary.otherCategory.length?'Звірка потребує уваги':'✓ Усі відібрані витрати розподілені')+'</b><p>Поїздки: '+money(totals.total)+' · Відібрано в реєстрі: '+money(summary.registerTotal)+' · Різниця: '+money(summary.difference)+'</p>'+(summary.unassigned.length?'<p>Відібрані, ще не прив’язані до поїздок: '+summary.unassigned.length+' операцій.</p>':'')+(summary.otherCategory.length?'<p>До поїздок прив’язані операції з інших категорій: '+summary.otherCategory.length+'.</p>':'')+'</div><div class="travelPending"><h3>Відібрані витрати для розподілу</h3><p>Позначайте потрібні операції у реєстрі витрат. Потім прив’яжіть їх до поїздки кнопкою «Редагувати» або створіть нову.</p>'+summary.unassigned.map(r=>'<div class="tripAssignment"><span>'+esc(displayDate(r.date))+' · '+esc(money(r.amount))+' · '+esc(r.description)+'</span><button data-new-trip="'+esc(r.id)+'">Створити поїздку</button></div>').join('')+'</div></section>';
document.querySelectorAll('[data-travel-amount]').forEach(b=>b.onclick=()=>openTravelCosts(JSON.parse(b.dataset.travelAmount)));
bindTravelSelection();document.querySelectorAll('[data-new-trip]').forEach(b=>b.onclick=()=>openTrip(null,data.records.find(r=>r.id===b.dataset.newTrip)));
$('#travelCsv').onclick=exportTravel;$('#travelPrint').onclick=()=>{document.body.classList.add('print-travel');window.print();};document.querySelectorAll('[data-trip]').forEach(b=>b.onclick=()=>openTrip((data.trips||[]).find(t=>t.id===b.dataset.trip)));
}
function exportTravel(){download('Steuerraum-Reisekosten-'+year+'.csv',SteuerraumFeatures.travelCsv(data.trips||[],data.records,year),'text/csv;charset=utf-8');}
let editingTrip=null,tripAutoValues={},tripTouched=new Set();
function openTrip(trip,record){if(SteuerraumFeatures.closedYear(data,(trip?.start||year).slice(0,4))){message('Рік закритий. Поїздки доступні лише для перегляду.',true);return;}
editingTrip=trip?structuredClone(trip):{id:crypto.randomUUID(),start:'',end:'',destination:'',purpose:'',costs:{tickets:[],accommodation:[],other:[]}};
if(record){const suggestion=SteuerraumFeatures.suggestTrip([record]);editingTrip={...editingTrip,start:suggestion.start,end:suggestion.end,destination:suggestion.destination,purpose:suggestion.purpose};editingTrip.costs[SteuerraumFeatures.travelCostType(record)]=[record.id];}
tripAutoValues={};tripTouched=new Set();const t=editingTrip,form=$('#tripForm');form.elements.tripStart.value=t.start;form.elements.tripEnd.value=t.end;form.elements.tripDestination.value=t.destination;form.elements.tripPurpose.value=t.purpose;$('#tripSuggestionNote').textContent='';for(const key of ['tripStart','tripEnd','tripDestination','tripPurpose']){tripAutoValues[key]=form.elements[key].value;form.elements[key].oninput=()=>tripTouched.add(key);}if(trip)for(const key of ['tripStart','tripEnd','tripDestination','tripPurpose'])if(form.elements[key].value)tripTouched.add(key);$('#tripError').textContent='';
const reserved=new Set((data.trips||[]).filter(x=>x.id!==t.id).flatMap(x=>SteuerraumFeatures.costTypes.flatMap(k=>x.costs[k]))),own=new Set(SteuerraumFeatures.costTypes.flatMap(k=>t.costs[k]));
const options=data.records.filter(r=>!SteuerraumFeatures.closedYear(data,r.date.slice(0,4))&&((SteuerraumFeatures.travelSelected(r,data.trips||[])&&r.date.startsWith(year))||own.has(r.id))).sort((a,b)=>a.date.localeCompare(b.date));
$('#tripAssignments').innerHTML=options.length?options.map(r=>{const assigned=SteuerraumFeatures.costTypes.find(k=>t.costs[k].includes(r.id))||'';return '<div class="tripAssignment"><span><b>'+esc(displayDate(r.date))+' · '+esc(money(r.amount))+'</b><small>'+esc(r.description)+(reserved.has(r.id)?' · Уже в іншій поїздці':'')+'</small></span><select data-cost-record="'+esc(r.id)+'" aria-label="Група витрати '+esc(r.description)+'" '+(reserved.has(r.id)?'disabled':'')+'><option value="">Не прив’язано</option>'+[['tickets','Tickets'],['accommodation','Accommodation'],['other','Other']].map(([key,label])=>'<option value="'+key+'" '+(assigned===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div>';}).join(''):'<p class="muted">Спочатку позначте потрібні витрати «Для таблиці подорожей» у реєстрі витрат.</p>';
document.querySelectorAll('[data-cost-record]').forEach(select=>select.onchange=fillTripFromRecords);fillTripFromRecords();$('#tripDetail').showModal();
}

function fillTripFromRecords(){const ids=new Set([...document.querySelectorAll('[data-cost-record]')].filter(select=>select.value&&!select.disabled).map(select=>select.dataset.costRecord));const suggestion=SteuerraumFeatures.suggestTrip(data.records.filter(r=>ids.has(r.id))),form=$('#tripForm');for(const [field,key] of [['tripStart','start'],['tripEnd','end'],['tripDestination','destination'],['tripPurpose','purpose']]){if(!tripTouched.has(field)&&form.elements[field].value===(tripAutoValues[field]||'')){form.elements[field].value=suggestion[key];tripAutoValues[field]=suggestion[key];}}$('#tripSuggestionNote').textContent=suggestion.ambiguousCity?'Вибрані витрати містять різні міста. Вкажи місце поїздки самостійно.':ids.size?'Місто, опис і дати підставлені з витрат, де ці дані відомі. Усе можна змінити.':'';}

$('#tripClose').onclick=()=>$('#tripDetail').close();
$('#tripForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,t={...editingTrip,start:form.elements.tripStart.value,end:form.elements.tripEnd.value,destination:form.elements.tripDestination.value.trim(),purpose:form.elements.tripPurpose.value.trim(),costs:{tickets:[],accommodation:[],other:[]}};document.querySelectorAll('[data-cost-record]').forEach(select=>{if(select.value&&!select.disabled)t.costs[select.value].push(select.dataset.costRecord);});try{const trips=SteuerraumFeatures.validateTrips([...(data.trips||[]).filter(x=>x.id!==t.id),t],data.records);if(persist({...data,trips})){$('#tripDetail').close();render();message('Поїздку збережено. Стан синхронізації — у блоці OneDrive.');}}catch(error){$('#tripError').textContent=error.message;}};
window.addEventListener('afterprint',()=>document.body.classList.remove('print-travel'));

function renderPeriod(){const locked=SteuerraumFeatures.closedYear(data,year),entry=data.closedYears?.[year];$('#periodStatus').textContent=locked?'🔒 '+year+' · Рік закритий · лише перегляд та експорт':'✎ '+year+' · Рік відкритий для редагування';$('#periodDate').textContent=locked?'Закрито '+new Date(entry.closedAt).toLocaleString('uk-UA'):entry?.reopenedAt?'Відкрито для редагування '+new Date(entry.reopenedAt).toLocaleString('uk-UA'):'Закриття фіксує всі витрати, документи й поїздки цього року.';$('#closeYear').hidden=locked;$('#reopenYear').hidden=!locked;$('#add').disabled=locked;}
$('#reopenYear').onclick=()=>{if(!confirm('Відкрити '+year+' рік для редагування? Знову стануть доступні додавання, зміни й видалення.'))return;try{const next=SteuerraumFeatures.reopenYear(data,year,new Date().toISOString());if(persist(next)){render();message('Рік '+year+' відкритий для редагування. Зміни синхронізуються автоматично.');}}catch(error){message(error.message,true);}};
$('#closeYear').onclick=()=>openYearAudit(true);


$('#recordDuplicate').onclick=()=>{if(!current)return;try{const copy=SteuerraumFeatures.duplicateRecord(data,current.id,crypto.randomUUID());$('#detail').close();openRecord(copy);$('#recordForm').elements.amount.focus();$('#recordForm').elements.amount.select();}catch(error){$('#recordReadOnly').textContent=error.message;}};

$('#recordDelete').onclick=()=>{if(!current||!confirm('Видалити цю витрату з реєстру та всіх поїздок? Файли в OneDrive залишаться.'))return;try{const next=SteuerraumFeatures.removeRecord(data,current.id);if(persist(next)){$('#detail').close();render();message('Витрату видалено з реєстру й таблиці подорожей.');}}catch(error){$('#recordReadOnly').textContent=error.message;}};

let inboxAuditState={status:'unknown',items:[],checkedAt:null},auditClosing=false;
function yearAuditPanel(){const audit=SteuerraumFeatures.completenessAudit(data,year,inboxAuditState);return '<h3>Повнота обліку · '+esc(year)+'</h3><div class="auditCounts"><span>Витрати без документа</span><b>'+audit.missing.length+'</b><span>Подорожі без розподілу</span><b>'+audit.unassigned.length+'</b><span>Дохід: група або надходження на перевірці</span><b>'+audit.incomeReview.length+'</b><span>Податки: рік або тип не визначений</span><b>'+audit.paymentReview.length+'</b><span>Нові комплекти в INBOX</span><b>'+(audit.inboxStatus==='ready'?audit.pending.length:'—')+'</b></div>'+(audit.unknown.length?'<p>Ще '+audit.unknown.length+' комплектів без року в назві.</p>':'')+'<p class="muted">'+esc(audit.inboxStatus==='ready'?'INBOX перевірено '+new Date(audit.checkedAt).toLocaleString('uk-UA'):audit.inboxStatus==='loading'?'Перевіряємо INBOX…':audit.inboxStatus==='error'?'INBOX зараз недоступний; його стан не підтверджений.':'INBOX ще не перевірений у цій сесії.')+'</p><button data-open-audit>Переглянути список</button>';}
function bindAuditButtons(){document.querySelectorAll('[data-open-audit]').forEach(b=>b.onclick=()=>openYearAudit());}
function setInboxAuditState(next){inboxAuditState={...inboxAuditState,...next};refreshAuditUi();}
function refreshAuditUi(){const audit=SteuerraumFeatures.completenessAudit(data,year,inboxAuditState);if($('#auditIssueCount'))$('#auditIssueCount').textContent=audit.issueCount;if($('#auditIssueLabel'))$('#auditIssueLabel').textContent=audit.issueCount?'Пункти для перегляду':audit.inboxStatus==='ready'?'Немає пунктів для перегляду':'INBOX ще не підтверджений';if($('#yearAudit')){$('#yearAudit').innerHTML=yearAuditPanel();bindAuditButtons();}if($('#auditDialog').open)renderAuditDetails();}
function auditRecordList(rows){return rows.length?rows.map(r=>'<button type="button" class="auditRecord" data-audit-record="'+esc(r.id)+'"><span>'+esc(displayDate(r.date))+' · '+esc(r.company||r.description)+'</span><b>'+esc(money(r.amount))+' ↗</b></button>').join(''):'<p class="muted">Немає.</p>';}
function renderAuditDetails(){const audit=SteuerraumFeatures.completenessAudit(data,year,inboxAuditState);$('#auditTitle').textContent=(auditClosing?'Перед закриттям року · ':'Повнота обліку · ')+year;const inboxGroups=[...audit.pending,...audit.unknown];$('#auditDetails').innerHTML='<h3>Без прикріпленого документа · '+audit.missing.length+'</h3>'+auditRecordList(audit.missing)+'<h3>Відібрані для подорожей, ще не розподілені · '+audit.unassigned.length+'</h3>'+auditRecordList(audit.unassigned)+'<h3>Дохід: перевірити групу або надходження · '+audit.incomeReview.length+'</h3>'+(audit.incomeReview.length?audit.incomeReview.map(r=>'<button type="button" class="auditRecord" data-audit-income="'+esc(r.id)+'"><span>'+esc(displayDate(r.date))+' · '+esc(r.company)+'</span><b>'+esc(money(r.amount))+' ↗</b></button>').join(''):'<p class="muted">Немає.</p>')+'<h3>Податки: перевірити рік або тип · '+audit.paymentReview.length+'</h3>'+(audit.paymentReview.length?audit.paymentReview.map(r=>'<button type="button" class="auditRecord" data-audit-payment="'+esc(r.id)+'"><span>'+esc(displayDate(r.date))+' · '+esc(r.company)+'</span><b>'+money(r.amount)+' ↗</b></button>').join(''):'<p class="muted">Немає.</p>')+'<h3>Ще не внесено з INBOX</h3>'+(audit.inboxStatus==='ready'?(inboxGroups.length?inboxGroups.map(g=>'<div class="auditInboxItem">'+esc(g.name)+(g.year?'':' · рік не визначений')+'<small>'+g.files.length+' файлів / папок</small></div>').join(''):'<p class="muted">Нових комплектів за цей рік немає.</p>'):'<p class="muted">'+(audit.inboxStatus==='loading'?'Перевіряємо папку…':'Стан INBOX не підтверджений. Натисніть «Перевірити INBOX».')+'</p>')+(auditClosing?'<p class="muted">Це список для перегляду. Ви можете закрити рік і за потреби відкрити його знову.</p>':'');document.querySelectorAll('[data-audit-income]').forEach(b=>b.onclick=()=>{const r=(data.incomeRecords||[]).find(r=>r.id===b.dataset.auditIncome);if(!r)return;$('#auditDialog').close();tab='income';year=r.date.slice(0,4);incomeGroup='';incomeQuery='';incomeOnlyReview=false;render();openIncomeRecord(r);});document.querySelectorAll('[data-audit-payment]').forEach(b=>b.onclick=()=>{const r=(data.taxPaymentRecords||[]).find(r=>r.id===b.dataset.auditPayment);if(!r)return;$('#auditDialog').close();tab='taxes';taxView=r.taxYear===year?'taxYear':'paidYear';render();openPaymentRecord('tax',r);});$('#auditConfirmClose').hidden=!auditClosing||SteuerraumFeatures.closedYear(data,year);$('#auditConfirmClose').disabled=audit.inboxStatus==='loading';document.querySelectorAll('[data-audit-record]').forEach(b=>b.onclick=()=>{const r=data.records.find(r=>r.id===b.dataset.auditRecord);if(!r)return;$('#auditDialog').close();tab='register';category='';query='';onlyMissing=false;year=r.date.slice(0,4);render();openRecord(r);});}
function openYearAudit(closing=false){auditClosing=closing;renderAuditDetails();$('#auditDialog').showModal();if(typeof window.refreshSteuerraumInbox==='function')window.refreshSteuerraumInbox();}
$('#auditClose').onclick=()=>$('#auditDialog').close();
$('#auditRefresh').onclick=()=>{if(typeof window.refreshSteuerraumInbox==='function')window.refreshSteuerraumInbox();else setInboxAuditState({status:'error'});};
$('#auditConfirmClose').onclick=()=>{const audit=SteuerraumFeatures.completenessAudit(data,year,inboxAuditState);if(!confirm('Закрити '+year+' рік? Пунктів для перегляду: '+audit.issueCount+'. '+(audit.inboxStatus!=='ready'?'Стан INBOX не підтверджений. ':'')+'Редагування буде заблоковане до повторного відкриття року.'))return;try{const next=SteuerraumFeatures.closeYear(data,year,new Date().toISOString());if(persist(next)){$('#auditDialog').close();render();message('Рік '+year+' закритий. Зміни синхронізуються автоматично.');}}catch(error){message(error.message,true);}};

function annualDetailsPanel(){const info=data.annualDetails?.[year]||{},locked=SteuerraumFeatures.closedYear(data,year);return '<section class="panel annualExtras"><div class="panelhead"><div><h2>Додаткові дані для податкової · '+esc(year)+'</h2><p>Окремо від бізнес-витрат. Ці значення не змінюють Betriebsausgaben або таблицю подорожей.</p></div></div><form id="annualDetailsForm"><fieldset><div class="formgrid"><div class="annualInsurance"><span>Krankenversicherung за рік</span><button type="button" id="annualInsuranceOpen">'+(SteuerraumFeatures.insuranceSummary(data,year).hasData?money(SteuerraumFeatures.insuranceSummary(data,year).total):'Ще немає даних')+' ↗</button><small>Підсумок окремого реєстру платежів</small></div><label>Відстань дім — офіс, км<input name="distanceKm" type="number" min="0" max="100000" step="any" value="'+(info.distanceKm==null?'':esc(info.distanceKm))+'"></label></div><div class="formgrid"><label>Адреса дому<textarea name="homeAddress">'+esc(info.homeAddress||'')+'</textarea></label><label>Адреса офісу<textarea name="officeAddress">'+esc(info.officeAddress||'')+'</textarea></label></div>'+(!locked?'<button class="primary" type="submit">Зберегти додаткові дані</button>':'<p class="muted">Рік закритий: лише перегляд.</p>')+'</fieldset><p id="annualDetailsMessage" role="status"></p></form></section>';}
function bindAnnualDetails(){document.querySelectorAll('#annualDetailsForm input,#annualDetailsForm textarea').forEach(el=>el.disabled=SteuerraumFeatures.closedYear(data,year));$('#annualInsuranceOpen').onclick=()=>{tab='insurance';render();};$('#annualDetailsForm').onsubmit=e=>{e.preventDefault();const form=new FormData(e.currentTarget),distance=String(form.get('distanceKm')).trim();try{const info={...(data.annualDetails?.[year]||{}),distanceKm:distance===''?null:Number(distance),homeAddress:String(form.get('homeAddress')).trim(),officeAddress:String(form.get('officeAddress')).trim(),updatedAt:new Date().toISOString()};if(persist(SteuerraumFeatures.saveAnnualDetails(data,year,info)))$('#annualDetailsMessage').textContent='Додаткові дані збережено. Статус синхронізації — угорі.';}catch(error){$('#annualDetailsMessage').textContent=error.message;}};}
function bankPeriodLabel(entry){if(!entry.periodFrom||!entry.coveredThrough)return 'Визначається з файла';return displayDate(entry.periodFrom)+' — '+displayDate(entry.coveredThrough)+(entry.periodBasis==='transactions'?' · дати операцій':'');}
function legacyBankImportPanel(){const coverage=SteuerraumFeatures.bankCoverage(data,year),bankPending=data.records.filter(r=>r.date.startsWith(year)&&r.bankReview==='pending').length,incomePending=(data.incomeRecords||[]).filter(r=>r.date.startsWith(year)&&r.bankReview==='pending').length,locked=SteuerraumFeatures.closedYear(data,year),labels={queued:'Очікує обробки',processing:'Обробляється',completed:'Оброблено',needs_review:'Потрібна перевірка',failed:'Не завершено'};return '<section class="panel bankImports"><div class="panelhead"><div><h2>Банківські виписки · '+esc(year)+'</h2><p>Повторні вивантаження за різні періоди: додаємо відсутні витрати й надходження. Ти перевіряєш записи та групи доходу.</p></div></div><div class="bankBody"><p><b>Підтверджене охоплення від початку року: '+(coverage.coveredThrough?esc(displayDate(coverage.coveredThrough)):coverage.imports.some(entry=>entry.status==='completed')?'дати операцій наведені в історії':'ще не оброблено')+'</b></p>'+ (coverage.latestUpload?'<p class="muted">Останнє завантаження: '+esc(new Date(coverage.latestUpload.uploadedAt).toLocaleString('uk-UA'))+' · період '+esc(bankPeriodLabel(coverage.latestUpload))+'</p>':'')+(!locked?'<form id="bankImportForm"><label>Файл банку: CSV, Excel або PDF<input type="file" name="statement" accept=".csv,.xlsx,.xls,.pdf,.txt" required></label><p class="muted">Період визначатиметься з файла автоматично. Файл надійде в INBOX і буде оброблений під час щоденної перевірки або за твоїм запитом. Завантаження файла ще не означає, що витрати внесені.</p><button type="submit" class="primary" id="bankImportSubmit">Завантажити виписку</button></form>':'<p class="muted">Щоб додати виписку, спочатку відкрий рік для редагування.</p>')+'<p id="bankImportMessage" role="status"></p>'+(bankPending?'<button type="button" id="bankReviewOpen">Перевірити нові витрати з банку · '+bankPending+'</button>':'')+(incomePending?'<button type="button" id="bankIncomeReviewOpen">Перевірити надходження з банку · '+incomePending+'</button>':'')+(coverage.imports.length?'<div class="tablewrap"><table><thead><tr><th>Завантажено</th><th>Період</th><th>Статус</th><th>Файл</th></tr></thead><tbody>'+coverage.imports.map(entry=>'<tr><td>'+esc(new Date(entry.uploadedAt).toLocaleDateString('uk-UA'))+'</td><td>'+esc(bankPeriodLabel(entry))+'</td><td>'+esc(labels[entry.status]||entry.status)+(entry.status==='completed'&&Number.isSafeInteger(entry.addedCount)?' · +'+entry.addedCount+' витрат · +'+(entry.addedIncomeCount||0)+' доходів':'')+'</td><td>'+(safeUrl(entry.sourceUrl)?'<a href="'+esc(safeUrl(entry.sourceUrl))+'" target="_blank" rel="noopener noreferrer">'+esc(entry.sourceName||'Виписка')+' ↗</a>':'—')+'</td></tr>').join('')+'</tbody></table></div>'+coverage.imports.filter(entry=>entry.unresolvedRows?.length).map(entry=>'<details class="bankAmbiguous"><summary>Потрібно звірити '+entry.unresolvedRows.length+' операцій · '+esc(entry.sourceName||'Виписка')+'</summary>'+entry.unresolvedRows.map(row=>'<div><p>'+esc(displayDate(row.date))+' · '+esc(row.company)+' · '+esc(money(row.amount))+'</p><p class="muted">'+esc(row.description)+'</p>'+(!locked?'<button type="button" data-bank-resolve="'+esc(JSON.stringify({batch:entry.id,key:row.sourceKey,action:'add',income:row.direction==='credit'}))+'">'+(row.direction==='credit'?'Додати як новий дохід':'Додати як нову витрату')+'</button>'+row.candidateIds.map(id=>{const record=(row.ledger==='insurance'?(data.insuranceRecords||[]):row.ledger==='tax'?(data.taxPaymentRecords||[]):row.direction==='credit'?(data.incomeRecords||[]):data.records).find(r=>r.id===id);return record?'<button type="button" data-bank-resolve="'+esc(JSON.stringify({batch:entry.id,key:row.sourceKey,action:'match',recordId:id}))+'">Вже є: '+esc(displayDate(record.date))+' · '+esc(record.company)+' · '+esc(money(record.amount))+'</button>':'';}).join(''):'')+'</div>').join('')+'</details>').join(''):'')+'</div></section>';}
function bindBankImport(){if($('#bankIncomeReviewOpen'))$('#bankIncomeReviewOpen').onclick=()=>{tab='income';incomeOnlyReview=true;incomeGroup='';incomeQuery='';render();};if($('#bankReviewOpen'))$('#bankReviewOpen').onclick=()=>{tab='register';onlyBankReview=true;onlyMissing=false;category='';query='';render();};document.querySelectorAll('[data-bank-resolve]').forEach(b=>b.onclick=()=>{const choice=JSON.parse(b.dataset.bankResolve);if(!confirm(choice.action==='add'?(choice.income?'Додати як окремий новий дохід?':'Додати як окрему нову витрату?'):'Підтвердити, що ця банківська операція вже врахована у вибраній витраті?'))return;try{if(persist(SteuerraumFeatures.resolveBankRow(data,choice.batch,choice.key,choice.action,choice.recordId,new Date().toISOString())))render();}catch(error){message(error.message,true);}});if(!$('#bankImportForm'))return;$('#bankImportForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,file=form.elements.statement.files[0],targetYear=year;if(!file)return;if(typeof window.uploadSteuerraumBank!=='function'){$('#bankImportMessage').textContent='Дочекайся підключення OneDrive.';return;}$('#bankImportSubmit').disabled=true;$('#bankImportMessage').textContent='Завантажуємо у приватний OneDrive…';try{const result=await window.uploadSteuerraumBank(file,{year:targetYear});if(tab==='overview'&&year===targetYear){render();$('#bankImportMessage').textContent=result.duplicate?'Цей файл уже завантажений. Повторної черги не створено.':'Виписку завантажено. Після обробки оновиться статус і дата звірки з банком.';}}catch(error){if($('#bankImportMessage'))$('#bankImportMessage').textContent=error.message;}finally{if($('#bankImportSubmit'))$('#bankImportSubmit').disabled=false;}};}

function taxOverviewPanel(){const calc=SteuerraumFeatures.taxOverview(data,year),paid=SteuerraumFeatures.taxPaymentSummary(data,year);return '<section class="panel taxOverview"><div class="panelhead"><div><h2>Розрахунок податку · '+esc(year)+'</h2><p>Дохід і витрати з реєстрів. Нижче — окремий орієнтовний розрахунок податків.</p></div></div><div class="taxNumbers"><div><span>Дохід</span><button type="button" id="taxIncomeOpen">'+money(calc.income)+' ↗</button><small>Із вкладки «Дохід»</small></div><div><span>Бізнес-витрати</span><b>'+money(calc.expenses)+'</b><small>Із реєстру витрат</small></div><div><span>Прибуток / збиток до податку</span><b>'+(calc.profit==null?'—':money(calc.profit))+'</b><small>'+(calc.hasIncome?'Дохід − бізнес-витрати':'Додай записи доходу для розрахунку')+'</small></div></div>'+(calc.unreviewedBankIncome||calc.unreviewedBankExpenses?'<p class="muted taxReviewNote">З банку на перевірці: '+calc.unreviewedBankIncome+' надходжень, '+calc.unreviewedBankExpenses+' витрат.</p>':'')+'<div class="taxPaidSummary"><span>Vorauszahlungen за '+esc(year)+': <b>'+money(paid.advance)+'</b></span><span>Nachzahlung / Jahresabrechnung за '+esc(year)+': <b>'+money(paid.assessment)+'</b></span><button id="taxPaymentsOpen" type="button">Сплачені податки ↗</button><small>Окремо від бізнес-витрат і прибутку.</small></div>'+taxEstimatePanel()+'</section>';}
function filteredIncome(){return (data.incomeRecords||[]).filter(r=>r.date.startsWith(year)&&(!incomeOnlyReview||r.bankReview==='pending')&&(!incomeGroup||(incomeGroup==='__unset'?!r.countryGroup:r.countryGroup===incomeGroup))&&[r.date,displayDate(r.date),r.company,r.description,r.countryGroup].join(' ').toLowerCase().includes(incomeQuery.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date));}
function renderIncome(){const summary=SteuerraumFeatures.incomeSummary(data,year);$('#view').innerHTML='<div class="incomeStats"><div class="stat"><span>Загальний дохід за рік</span><b>'+money(summary.total)+'</b>'+(summary.unassigned.length?'<small>Зокрема без групи: '+money(summary.groups[''])+' · '+summary.unassigned.length+' записів</small>':'')+'</div>'+SteuerraumFeatures.incomeCountryGroups.map(group=>'<div class="stat"><span>'+esc(group)+'</span><b>'+money(summary.groups[group])+'</b></div>').join('')+'</div><section class="panel"><div class="filters"><input id="incomeSearch" type="search" aria-label="Пошук доходу" placeholder="Платник, опис або дата…" value="'+esc(incomeQuery)+'"><select id="incomeGroupFilter" aria-label="Фільтр за групою доходу"><option value="">Усі групи</option>'+SteuerraumFeatures.incomeCountryGroups.map(group=>'<option value="'+esc(group)+'" '+(incomeGroup===group?'selected':'')+'>'+esc(group)+'</option>').join('')+'<option value="__unset" '+(incomeGroup==='__unset'?'selected':'')+'>Без групи</option></select><label><input id="incomeReviewFilter" type="checkbox" '+(incomeOnlyReview?'checked':'')+'>З банку — на перевірці</label></div><p class="muted incomeNote">Europäische Union — країни ЄС, окрім Німеччини. Групу можна вибрати в кожному рядку.</p><div class="tablewrap"><table><thead><tr><th>Дата</th><th>Платник</th><th>Опис</th><th>Група</th><th class="amount">Сума</th><th>Дії</th></tr></thead><tbody id="incomeRows"></tbody></table></div><div id="incomeFoot" class="tablefoot"></div></section>';renderIncomeRows();$('#incomeSearch').oninput=e=>{incomeQuery=e.target.value;renderIncomeRows();};$('#incomeGroupFilter').onchange=e=>{incomeGroup=e.target.value;renderIncomeRows();};$('#incomeReviewFilter').onchange=e=>{incomeOnlyReview=e.target.checked;renderIncomeRows();};}
function renderIncomeRows(){const rows=filteredIncome();$('#incomeRows').innerHTML=rows.map(r=>{const locked=SteuerraumFeatures.closedYear(data,r.date.slice(0,4));return '<tr><td>'+esc(displayDate(r.date))+'</td><td>'+esc(r.company)+'</td><td>'+esc(r.description)+(r.bankReview==='pending'?'<small>Надходження з банку · перевір групу й призначення</small>':'')+'</td><td><select data-income-group="'+esc(r.id)+'" aria-label="Група доходу від '+esc(r.company)+'" '+(locked?'disabled':'')+'><option value="">Не визначено</option>'+SteuerraumFeatures.incomeCountryGroups.map(group=>'<option value="'+esc(group)+'" '+(r.countryGroup===group?'selected':'')+'>'+esc(group)+'</option>').join('')+'</select></td><td class="amount">'+money(r.amount)+'</td><td><button type="button" data-open-income="'+esc(r.id)+'">'+(locked?'Переглянути':'Редагувати')+'</button></td></tr>';}).join('');$('#incomeFoot').innerHTML='<span>'+rows.length+' записів</span><b>'+money(rows.reduce((s,r)=>s+r.amount,0))+'</b>';document.querySelectorAll('[data-open-income]').forEach(b=>b.onclick=()=>openIncomeRecord(data.incomeRecords.find(r=>r.id===b.dataset.openIncome)));document.querySelectorAll('[data-income-group]').forEach(select=>select.onchange=()=>{const old=data.incomeRecords.find(r=>r.id===select.dataset.incomeGroup),record={...old,countryGroup:select.value,...(old.bankReview?{bankReview:select.value?'reviewed':'pending'}:{})};try{if(persist(SteuerraumFeatures.saveIncomeRecord(data,record)))renderIncome();else select.value=old.countryGroup||'';}catch(error){select.value=old.countryGroup||'';message(error.message,true);}});}
function openIncomeRecord(record){incomeCurrent=record?structuredClone(record):{id:crypto.randomUUID(),date:year+'-01-01',amount:0,company:'',description:'',countryGroup:''};const form=$('#incomeForm'),r=incomeCurrent,locked=SteuerraumFeatures.closedYear(data,r.date.slice(0,4));form.elements.incomeDate.value=r.date;form.elements.incomeAmount.value=r.amount?(r.amount/100).toFixed(2):'';form.elements.incomeCompany.value=r.company;form.elements.incomeDescription.value=r.description;form.elements.incomeCountry.innerHTML='<option value="">Не визначено</option>'+SteuerraumFeatures.incomeCountryGroups.map(group=>'<option>'+esc(group)+'</option>').join('');form.elements.incomeCountry.value=r.countryGroup||'';document.querySelectorAll('#incomeForm input,#incomeForm textarea,#incomeForm select').forEach(el=>el.disabled=locked);$('#incomeSave').hidden=locked;$('#incomeDelete').hidden=locked||!(data.incomeRecords||[]).some(x=>x.id===r.id);$('#incomeError').textContent=locked?'Рік закритий: лише перегляд.':'';$('#incomeDetail').showModal();}
$('#incomeClose').onclick=()=>$('#incomeDetail').close();
$('#incomeForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,record={...incomeCurrent,date:form.elements.incomeDate.value,amount:Math.round(Number(form.elements.incomeAmount.value)*100),company:form.elements.incomeCompany.value.trim(),description:form.elements.incomeDescription.value.trim(),countryGroup:form.elements.incomeCountry.value};if(record.bankReview&&record.countryGroup)record.bankReview='reviewed';try{if(persist(SteuerraumFeatures.saveIncomeRecord(data,record))){$('#incomeDetail').close();render();}}catch(error){$('#incomeError').textContent=error.message;}};
$('#incomeDelete').onclick=()=>{if(!incomeCurrent||!confirm('Видалити цей запис доходу?'))return;try{if(persist(SteuerraumFeatures.removeIncomeRecord(data,incomeCurrent.id))){$('#incomeDetail').close();render();}}catch(error){$('#incomeError').textContent=error.message;}};

function paymentRows(type){const rows=(data[SteuerraumFeatures.paymentArray(type)]||[]).filter(r=>type!=='tax'||!taxTypeFilter||(r.taxType||'unknown')===taxTypeFilter);return rows.filter(r=>type==='insurance'?r.reportYear===year:taxView==='paidYear'?r.date.startsWith(year):r.taxYear===year);}
function filteredPayments(type){return paymentRows(type).filter(r=>(!paymentKind||(type==='insurance'?r.direction===paymentKind:r.kind===paymentKind))&&[r.date,displayDate(r.date),r.company,r.description,r.taxYear,r.reportYear].join(' ').toLowerCase().includes(paymentQuery.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date));}
function paymentLocked(record,type){return SteuerraumFeatures.closedYear(data,record.date.slice(0,4))||SteuerraumFeatures.closedYear(data,type==='insurance'?record.reportYear:record.taxYear||record.date.slice(0,4));}
function legacyStatementPanel(type){const coverage=SteuerraumFeatures.bankCoverage(data,year,type),locked=SteuerraumFeatures.closedYear(data,year),labels={queued:'Очікує обробки',processing:'Обробляється',completed:'Оброблено',needs_review:'Потрібна звірка',failed:'Не завершено'};return '<section class="panel paymentStatements"><div class="panelhead"><div><h2>Виписки · '+(type==='insurance'?'Krankenversicherung':'Податки')+'</h2><p>Період визначаємо з файла. Платежі потрапляють тільки в цей окремий реєстр.</p></div></div><div class="bankBody">'+(!locked?'<form id="statementForm"><label>CSV, Excel або PDF<input type="file" name="statement" accept=".csv,.xlsx,.xls,.pdf,.txt" required></label><button id="statementUpload" type="submit" class="primary">Завантажити виписку</button></form>':'<p class="muted">Щоб додати виписку, відкрий рік для редагування.</p>')+'<p id="statementMessage" role="status"></p>'+coverage.imports.map(entry=>'<div class="statementHistory"><span>'+esc(new Date(entry.uploadedAt).toLocaleDateString('uk-UA'))+' · '+esc(bankPeriodLabel(entry))+' · '+esc(labels[entry.status])+'</span> '+(safeUrl(entry.sourceUrl)?'<a href="'+esc(safeUrl(entry.sourceUrl))+'" target="_blank" rel="noopener noreferrer">Файл ↗</a>':'')+(entry.unresolvedRows?.length?'<details><summary>Потрібно звірити '+entry.unresolvedRows.length+' платежів</summary>'+entry.unresolvedRows.map(row=>'<div><p>'+esc(displayDate(row.date))+' · '+esc(row.company)+' · '+money(row.amount)+'</p>'+(!locked?'<button type="button" data-resolve-payment="'+esc(JSON.stringify({batch:entry.id,key:row.sourceKey,action:'add'}))+'">Додати окремий платіж</button>'+row.candidateIds.map(id=>{const old=(data[SteuerraumFeatures.paymentArray(type)]||[]).find(r=>r.id===id);return old?'<button type="button" data-resolve-payment="'+esc(JSON.stringify({batch:entry.id,key:row.sourceKey,action:'match',recordId:id}))+'">Вже є: '+esc(displayDate(old.date))+' · '+money(old.amount)+'</button>':'';}).join(''):'')+'</div>').join('')+'</details>':'')+'</div>').join('')+'</div></section>';}
function renderPaymentLedger(type){if(paymentType!==type){paymentQuery='';paymentKind='';}paymentType=type;const base=paymentRows(type),insurance=SteuerraumFeatures.insuranceSummary(data,year),advance=base.filter(r=>r.kind==='advance').reduce((s,r)=>s+r.amount,0),assessment=base.filter(r=>r.kind==='assessment').reduce((s,r)=>s+r.amount,0),refund=base.filter(r=>r.kind==='refund').reduce((s,r)=>s+r.amount,0),kinds=type==='insurance'?[['debit','Versicherungsbeitrag'],['credit','Erstattung']]:[['advance','Vorauszahlung'],['assessment','Nachzahlung / Jahresabrechnung'],['refund','Erstattung'],['unknown','Не визначено']];$('#view').innerHTML='<div class="stats">'+(type==='insurance'?'<div class="stat"><span>Внески</span><b>'+(insurance.legacyUsed?'—':money(insurance.paid))+'</b></div><div class="stat"><span>Повернення</span><b>'+(insurance.legacyUsed?'—':money(insurance.refunded))+'</b></div><div class="stat"><span>Krankenversicherung · '+esc(year)+'</span><b>'+(insurance.hasData?money(insurance.total):'—')+'</b></div>':'<div class="stat"><span>Vorauszahlung</span><b>'+money(advance)+'</b></div><div class="stat"><span>Nachzahlung / Jahresabrechnung</span><b>'+money(assessment)+'</b></div><div class="stat"><span>Erstattung</span><b>'+money(refund)+'</b></div>')+'</div><section class="panel"><div class="filters"><input type="search" id="paymentSearch" placeholder="Отримувач, опис або дата…" aria-label="Пошук платежів" value="'+esc(paymentQuery)+'"><select id="paymentKindFilter" aria-label="Тип платежу"><option value="">Усі типи</option>'+kinds.map(([value,label])=>'<option value="'+value+'" '+(paymentKind===value?'selected':'')+'>'+esc(label)+'</option>').join('')+'</select>'+(type==='tax'?'<select id="taxTypeFilter" aria-label="Вид податку">'+statementOptions([['','Усі податки'],['Einkommensteuer','Einkommensteuer'],['Gewerbesteuer','Gewerbesteuer'],['unknown','Не визначено']],taxTypeFilter)+'</select><select id="taxYearMode" aria-label="Відбір року"><option value="paidYear" '+(taxView==='paidYear'?'selected':'')+'>Сплачено у '+esc(year)+'</option><option value="taxYear" '+(taxView==='taxYear'?'selected':'')+'>За податковий рік '+esc(year)+'</option></select>':'')+'</div><p class="muted incomeNote">'+(type==='insurance'?(insurance.legacyUsed?'У зведенні за цей рік збережено '+money(insurance.total)+'. Детальні платежі ще не внесені; ця сума не додається повторно до платежів.':'Окремо від бізнес-витрат. В огляд року підтягується сума внесків мінус повернення.'):'Дата оплати та податковий рік — різні поля. Податки не зменшують бізнес-витрати або прибуток у цьому огляді.')+'</p><div class="tablewrap"><table><thead><tr><th>Дата оплати</th><th>Отримувач</th><th>Опис</th><th>'+ (type==='insurance'?'Рік внеску':'Податковий рік')+'</th><th>Тип</th><th class="amount">Сума</th><th>Дії</th><th>Файл</th></tr></thead><tbody id="paymentRows"></tbody></table></div><div class="tablefoot" id="paymentFoot"></div></section>';renderPaymentRows(type);$('#paymentSearch').oninput=e=>{paymentQuery=e.target.value;renderPaymentRows(type);};$('#paymentKindFilter').onchange=e=>{paymentKind=e.target.value;renderPaymentRows(type);};if(type==='tax')$('#taxTypeFilter').onchange=e=>{taxTypeFilter=e.target.value;renderPaymentLedger(type);};if(type==='tax')$('#taxYearMode').onchange=e=>{taxView=e.target.value;renderPaymentLedger(type);};}
function renderPaymentRows(type){const rows=filteredPayments(type),kinds=type==='insurance'?[['debit','Versicherungsbeitrag'],['credit','Erstattung']]:[['unknown','Не визначено'],['advance','Vorauszahlung'],['assessment','Nachzahlung / Jahresabrechnung'],['refund','Erstattung']];$('#paymentRows').innerHTML=rows.map(r=>{const locked=paymentLocked(r,type),value=type==='insurance'?r.direction:r.kind;return '<tr><td>'+esc(displayDate(r.date))+(type==='tax'?'<label class="paidTaxChoice">Вид податку<select aria-label="Вид податку" data-payment-tax-type="'+esc(r.id)+'" '+(locked?'disabled':'')+'>'+statementOptions([['unknown','Обери вид податку'],['Einkommensteuer','Einkommensteuer'],['Gewerbesteuer','Gewerbesteuer']],r.taxType||'unknown')+'</select></label>':'')+'</td><td>'+esc(r.company)+'</td><td>'+esc(r.description)+'</td><td>'+(type==='tax'?'<input type="number" min="1900" max="2200" class="paymentYear" data-payment-year="'+esc(r.id)+'" aria-label="Податковий рік" placeholder="Рік" value="'+esc(r.taxYear||'')+'" '+(locked?'disabled':'')+'>':esc(r.reportYear))+'</td><td><select data-payment-kind="'+esc(r.id)+'" aria-label="Тип платежу" '+(locked?'disabled':'')+'>'+kinds.map(([key,label])=>'<option value="'+key+'" '+(value===key?'selected':'')+'>'+esc(label)+'</option>').join('')+'</select></td><td class="amount">'+(type==='insurance'&&r.direction==='credit'||type==='tax'&&r.kind==='refund'?'−':'')+money(r.amount)+'</td><td><button data-open-payment="'+esc(r.id)+'" type="button">'+(locked?'Переглянути':'Редагувати')+'</button></td><td>'+(safeUrl(r.bankStatementUrl)?'<a href="'+esc(safeUrl(r.bankStatementUrl))+'" target="_blank" rel="noopener noreferrer">Файл ↗</a>':'—')+'</td></tr>';}).join('');$('#paymentFoot').innerHTML='<span>'+rows.length+' платежів</span><b>'+money(rows.reduce((sum,r)=>sum+(type==='insurance'&&r.direction==='credit'||type==='tax'&&r.kind==='refund'?-r.amount:r.amount),0))+'</b>';document.querySelectorAll('[data-open-payment]').forEach(b=>b.onclick=()=>openPaymentRecord(type,(data[SteuerraumFeatures.paymentArray(type)]||[]).find(r=>r.id===b.dataset.openPayment)));const update=(id,fields)=>{const old=data[SteuerraumFeatures.paymentArray(type)].find(r=>r.id===id);try{if(persist(SteuerraumFeatures.savePaymentRecord(data,type,{...old,...fields})))renderPaymentLedger(type);}catch(error){message(error.message,true);renderPaymentLedger(type);}};document.querySelectorAll('[data-payment-kind]').forEach(select=>select.onchange=()=>update(select.dataset.paymentKind,type==='insurance'?{direction:select.value}:{kind:select.value}));document.querySelectorAll('[data-payment-tax-type]').forEach(select=>select.onchange=()=>update(select.dataset.paymentTaxType,{taxType:select.value}));document.querySelectorAll('[data-payment-year]').forEach(input=>input.onchange=()=>update(input.dataset.paymentYear,{taxYear:input.value||null}));}
function bindPaymentStatement(type){document.querySelectorAll('[data-resolve-payment]').forEach(b=>b.onclick=()=>{const choice=JSON.parse(b.dataset.resolvePayment);if(!confirm(choice.action==='add'?'Додати окремий платіж?':'Підтвердити збіг із наявним платежем?'))return;try{if(persist(SteuerraumFeatures.resolveBankRow(data,choice.batch,choice.key,choice.action,choice.recordId,new Date().toISOString())))renderPaymentLedger(type);}catch(error){message(error.message,true);}});if(!$('#statementForm'))return;$('#statementForm').onsubmit=async e=>{e.preventDefault();const file=e.currentTarget.elements.statement.files[0],targetYear=year;if(!file)return;if(typeof window.uploadSteuerraumBank!=='function'){$('#statementMessage').textContent='Дочекайся підключення OneDrive.';return;}$('#statementUpload').disabled=true;try{await window.uploadSteuerraumBank(file,{year:targetYear,ledger:type});if(year===targetYear&&paymentType===type){renderPaymentLedger(type);$('#statementMessage').textContent='Виписку завантажено до INBOX для обробки.';}}catch(error){if($('#statementMessage'))$('#statementMessage').textContent=error.message;}finally{if($('#statementUpload'))$('#statementUpload').disabled=false;}};}
function openPaymentRecord(type,record){paymentType=type;paymentCurrent=record?structuredClone(record):{id:type+'-'+crypto.randomUUID(),date:year+'-01-01',amount:0,company:'',description:'',...(type==='insurance'?{reportYear:year,direction:'debit'}:{taxYear:year,kind:'unknown'})};const r=paymentCurrent,form=$('#paymentForm'),locked=paymentLocked(r,type);$('#paymentTitle').textContent=type==='insurance'?'Krankenversicherung':'Сплачений податок';form.elements.paymentDate.value=r.date;form.elements.paymentAmount.value=r.amount?(r.amount/100).toFixed(2):'';form.elements.paymentCompany.value=r.company;form.elements.paymentDescription.value=r.description;form.elements.paymentYear.value=type==='insurance'?r.reportYear:r.taxYear||'';$('#paymentYearLabel').textContent=type==='insurance'?'Рік внеску':'Податковий рік';const kinds=type==='insurance'?[['debit','Versicherungsbeitrag'],['credit','Erstattung']]:[['unknown','Не визначено'],['advance','Vorauszahlung'],['assessment','Nachzahlung / Jahresabrechnung'],['refund','Erstattung']];form.elements.paymentKind.innerHTML=kinds.map(([value,label])=>'<option value="'+value+'">'+esc(label)+'</option>').join('');$('#paymentTaxTypeLabel').hidden=type!=='tax';form.elements.paymentTaxType.value=r.taxType||'unknown';form.elements.paymentKind.value=type==='insurance'?r.direction:r.kind;document.querySelectorAll('#paymentForm input,#paymentForm textarea,#paymentForm select').forEach(el=>el.disabled=locked);$('#paymentSave').hidden=locked;$('#paymentDelete').hidden=locked||!(data[SteuerraumFeatures.paymentArray(type)]||[]).some(x=>x.id===r.id);$('#paymentError').textContent=locked?'Рік закритий: лише перегляд.':'';$('#paymentDetail').showModal();}
$('#paymentClose').onclick=()=>$('#paymentDetail').close();
$('#paymentForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,r={...paymentCurrent,date:form.elements.paymentDate.value,amount:Math.round(Number(form.elements.paymentAmount.value)*100),company:form.elements.paymentCompany.value.trim(),description:form.elements.paymentDescription.value.trim(),...(paymentType==='insurance'?{reportYear:form.elements.paymentYear.value,direction:form.elements.paymentKind.value}:{taxType:form.elements.paymentTaxType.value,taxYear:form.elements.paymentYear.value||null,kind:form.elements.paymentKind.value})};try{if(persist(SteuerraumFeatures.savePaymentRecord(data,paymentType,r))){$('#paymentDetail').close();render();}}catch(error){$('#paymentError').textContent=error.message;}};
$('#paymentDelete').onclick=()=>{if(!paymentCurrent||!confirm('Видалити цей платіж?'))return;try{if(persist(SteuerraumFeatures.removePaymentRecord(data,paymentType,paymentCurrent.id))){$('#paymentDetail').close();render();}}catch(error){$('#paymentError').textContent=error.message;}};


let statementSelection='',statementSearch='',statementLedger='',statementCategory='';
const statementLabels={expense:'Бізнес-витрати',income:'Дохід',insurance:'Krankenversicherung',tax:'Податки',ignore:'Не вносити'};
function bankImportPanel(){return '<section class="panel bankBody"><h2>Банківські виписки</h2><p>Завантаження та розподіл усіх виписок — в одному місці.</p><button type="button" onclick="tab=\'imports\';render()">Відкрити імпорт виписок</button></section>';}
function statementPanel(){return bankImportPanel();}
function statementOptions(values,value){return values.map(([key,label])=>'<option value="'+esc(key)+'" '+(String(value||'')===key?'selected':'')+'>'+esc(label)+'</option>').join('');}
function activeStatement(){return (data.bankImports||[]).find(x=>x.id===statementSelection);}
function visibleStatementRows(entry){return (entry.previewRows||[]).filter(r=>(!statementLedger||r.ledger===statementLedger)&&(!statementCategory||r.category===statementCategory)&&(!statementSearch||(r.date+' '+r.company+' '+r.description).toLowerCase().includes(statementSearch.toLowerCase())));}
function renderStatementImports(){
const imports=[...(data.bankImports||[])].sort((a,b)=>b.uploadedAt.localeCompare(a.uploadedAt));
if(!imports.some(x=>x.id===statementSelection))statementSelection=imports[0]?.id||'';
const entry=activeStatement(),labels={queued:'Очікує підготовки',processing:'Готується',needs_review:'Перевір розподіл',completed:'Внесено',failed:'Потрібна увага'};
$('#view').innerHTML='<section class="panel bankBody"><h2>Завантажити файл</h2><form id="centralStatementForm"><label>CSV, Excel або PDF<input type="file" name="statement" accept=".csv,.xlsx,.xls,.pdf,.txt" required></label><button class="primary" id="centralStatementUpload">Завантажити</button></form><p id="centralStatementMessage" role="status">Спочатку готуємо розподіл. Внесення до реєстрів — після твого підтвердження.</p></section><section class="panel bankBody"><h2>Розподіл виписки</h2><label>Виписка<select id="statementSelection">'+imports.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===statementSelection?'selected':'')+'>'+esc(x.sourceName||'Виписка')+' · '+esc(labels[x.status]||x.status)+'</option>').join('')+'</select></label><div id="statementPreview"></div></section>';
$('#centralStatementForm').onsubmit=async e=>{e.preventDefault();const file=e.currentTarget.elements.statement.files[0];if(!file)return;$('#centralStatementUpload').disabled=true;try{if(typeof window.uploadSteuerraumBank!=='function')throw Error('Підключи OneDrive.');const result=await window.uploadSteuerraumBank(file,{unassigned:true});statementSelection=result.entry.id;renderStatementImports();$('#centralStatementMessage').textContent=result.duplicate?'Ця виписка вже завантажена. Відкрито її поточний стан.':'Файл збережено в INBOX. Розподіл з’явиться після обробки за запитом або щоденної перевірки.';}catch(error){$('#centralStatementMessage').textContent=error.message;}finally{if($('#centralStatementUpload'))$('#centralStatementUpload').disabled=false;}};
$('#statementSelection').onchange=e=>{statementSelection=e.target.value;statementSearch='';statementLedger='';statementCategory='';renderStatementPreview();};renderStatementPreview();renderInboxProcessingLog();
}
function renderStatementPreview(){
let entry=activeStatement();if(entry?.previewRows?.length&&entry.status!=='completed'&&!SteuerraumFeatures.closedYear(data,entry.year)){const suggested=SteuerraumFeatures.suggestStatementCategories(entry.previewRows);if(JSON.stringify(suggested)!==JSON.stringify(entry.previewRows)){try{persist(SteuerraumFeatures.saveStatementPreview(data,entry.id,suggested));entry=activeStatement();}catch(error){message(error.message,true);}}}const host=$('#statementPreview');if(!entry){host.innerHTML='<p>Ще немає виписок.</p>';return;}
const locked=entry.status==='completed'||SteuerraumFeatures.closedYear(data,entry.year),rows=entry.previewRows||[];
host.innerHTML='<p>'+esc(entry.year||'Рік визначається з файла')+' · '+esc(bankPeriodLabel(entry))+' '+(safeUrl(entry.sourceUrl)?'<a target="_blank" rel="noopener noreferrer" href="'+esc(safeUrl(entry.sourceUrl))+'">Файл ↗</a>':'')+'</p>'+(!rows.length?'<p>Файл завантажено. Операції ще очікують підготовки розподілу.</p>':'<p>'+rows.length+' операцій · '+(entry.status==='completed'?'Внесено до реєстрів.':'Це попередній розподіл. Реєстри ще не змінені.')+'</p><div class="filters"><input id="statementSearch" type="search" placeholder="Дата, контрагент, опис" value="'+esc(statementSearch)+'"><select id="statementLedger">'+statementOptions([['','Усі розділи'],...Object.entries(statementLabels)],statementLedger)+'</select><select id="statementCategory">'+statementOptions([['','Усі статті'],[SteuerraumFeatures.BANK_REVIEW_CATEGORY,'Без статті'],...cats().map(c=>[c,c])],statementCategory)+'</select></div>'+(!locked?'<div class="actions"><select id="statementBulkCategory">'+statementOptions([['','Стаття для відібраних витрат'],...cats().map(c=>[c,c])],'')+'</select><button id="statementBulkApply" type="button">Призначити відібраним</button></div>':'')+'<div class="tablewrap"><table class="register statementPreviewTable"><thead><tr><th>Внести</th><th>Дата</th><th>Контрагент / опис</th><th>Сума</th><th>Розділ</th><th>Стаття / група</th></tr></thead><tbody id="statementPreviewRows"></tbody></table></div><p id="statementPreviewCount"></p>'+(!locked?'<button class="primary" id="statementCommit" type="button">Підтвердити й внести до реєстрів</button>':'<p>Лише перегляд.</p>'));
if(entry.status==='completed'){const button=document.createElement('button');button.type='button';button.textContent='Скасувати цей імпорт';button.disabled=SteuerraumFeatures.closedYear(data,entry.year);button.onclick=()=>openStatementUndo(entry.id);host.appendChild(button);}if(!rows.length)return;
$('#statementSearch').oninput=e=>{statementSearch=e.target.value;renderStatementPreviewRows();};$('#statementLedger').onchange=e=>{statementLedger=e.target.value;renderStatementPreviewRows();};$('#statementCategory').onchange=e=>{statementCategory=e.target.value;renderStatementPreviewRows();};
if(!locked){$('#statementBulkApply').onclick=()=>{const value=$('#statementBulkCategory').value;if(!value)return;const keys=new Set(visibleStatementRows(activeStatement()).filter(r=>r.ledger==='expense'&&r.included&&!r.matchId).map(r=>r.sourceKey));updateStatementRows(SteuerraumFeatures.suggestStatementCategories(activeStatement().previewRows.map(r=>keys.has(r.sourceKey)?{...r,category:value,categorySelection:'manual',categorySuggestedBy:null}:r)));};
$('#statementCommit').onclick=()=>{const e=activeStatement(),n=e.previewRows.filter(r=>r.included&&r.ledger!=='ignore'&&!r.matchId).length;if(!confirm('Внести '+n+' нових операцій за поточним розподілом? Наявні збіги не дублюватимуться.'))return;try{if(persist(SteuerraumFeatures.commitStatementPreview(data,e.id,new Date().toISOString()))){renderStatementPreview();message('Виписку внесено за підтвердженим розподілом.');}}catch(error){message(error.message,true);}};}renderStatementPreviewRows();
}
function updateStatementRows(rows){try{if(persist(SteuerraumFeatures.saveStatementPreview(data,statementSelection,rows)))renderStatementPreviewRows();}catch(error){message(error.message,true);}}
function renderStatementPreviewRows(){
const entry=activeStatement(),rows=visibleStatementRows(entry),locked=entry.status==='completed'||SteuerraumFeatures.closedYear(data,entry.year);
$('#statementPreviewRows').innerHTML=rows.map(r=>{const disabled=locked||r.matchId?'disabled':'',sectionValues=[...Object.entries(statementLabels),['tax:Einkommensteuer','Податки · Einkommensteuer'],['tax:Gewerbesteuer','Податки · Gewerbesteuer']].filter(([key])=>!(r.direction==='credit'&&key==='expense'||r.direction==='debit'&&key==='income'));
let choices=r.ledger==='expense'?'<select data-preview-field="category" '+disabled+'>'+statementOptions([[SteuerraumFeatures.BANK_REVIEW_CATEGORY,'Без статті'],...cats().map(c=>[c,c])],r.category)+'</select>':r.ledger==='income'?'<select data-preview-field="countryGroup" '+disabled+'>'+statementOptions([['','Не визначено'],...SteuerraumFeatures.incomeCountryGroups.map(c=>[c,c])],r.countryGroup)+'</select>':r.ledger==='tax'?'<select data-preview-field="kind" '+disabled+'>'+statementOptions([['unknown','Не визначено'],['advance','Vorauszahlung'],['assessment','Nachzahlung / Jahresabrechnung'],['refund','Erstattung']],r.kind)+'</select><select aria-label="Вид податку" data-preview-field="taxType" '+disabled+'>'+statementOptions([['unknown','Не визначено'],['Einkommensteuer','Einkommensteuer'],['Gewerbesteuer','Gewerbesteuer']],r.taxType||'unknown')+'</select><input type="number" min="1900" max="2200" aria-label="Податковий рік" data-preview-field="taxYear" value="'+esc(r.taxYear||'')+'" '+disabled+'>':r.ledger==='insurance'?'<input type="number" min="1900" max="2200" aria-label="Рік внеску" data-preview-field="reportYear" value="'+esc(r.reportYear||r.date.slice(0,4))+'" '+disabled+'>':'—';
const sourceRecords=r.ledger==='expense'?data.records:r.ledger==='income'?(data.incomeRecords||[]):r.ledger==='insurance'?(data.insuranceRecords||[]):r.ledger==='tax'?(data.taxPaymentRecords||[]):[];const candidates=sourceRecords.filter(x=>x.amount===r.amount&&Math.abs(Date.parse(x.date)-Date.parse(r.date))<=7*86400000||x.id===r.matchId);if(candidates.length&&!locked)choices+='<select data-preview-field="matchId" aria-label="Збіг із реєстром">'+statementOptions([['','Перевір можливий збіг'],['__new','Окрема нова операція'],...candidates.map(x=>[x.id,'Вже є: '+displayDate(x.date)+' · '+x.company])],r.matchId||(r.forceNew?'__new':''))+'</select>';return '<tr data-preview-key="'+esc(r.sourceKey)+'"><td>'+(r.matchId?'Вже є':'<input type="checkbox" aria-label="Внести операцію" data-preview-field="included" '+(r.included?'checked':'')+' '+disabled+'>')+'</td><td>'+esc(displayDate(r.date))+'</td><td><b>'+esc(r.company)+'</b><small class="statementDescription" title="'+esc(r.description)+'">'+esc(r.description)+'</small></td><td class="amount">'+(r.direction==='debit'?'−':'＋')+money(r.amount)+'</td><td><select data-preview-field="ledger" '+disabled+'>'+statementOptions(sectionValues,r.ledger==='tax'&&['Einkommensteuer','Gewerbesteuer'].includes(r.taxType)?'tax:'+r.taxType:r.ledger)+'</select></td><td>'+choices+(r.categorySelection==='auto'?'<small class="muted">Автопідбір · можна змінити</small>':'')+'</td></tr>';}).join('');
$('#statementPreviewCount').textContent='Показано '+rows.length+' із '+entry.previewRows.length;
document.querySelectorAll('[data-preview-field]').forEach(el=>el.onchange=()=>{const key=el.closest('[data-preview-key]').dataset.previewKey,field=el.dataset.previewField,value=field==='included'?el.checked:el.value;if(field==='ledger'&&value.startsWith('tax:')){updateStatementRows(activeStatement().previewRows.map(r=>r.sourceKey===key?{...r,ledger:'tax',taxType:value.slice(4),included:true,matchId:null,forceNew:false}:r));return;}if(field==='category'){try{updateStatementRows(SteuerraumFeatures.suggestStatementCategories(activeStatement().previewRows,key,value));}catch(error){message(error.message,true);}return;}updateStatementRows(activeStatement().previewRows.map(r=>r.sourceKey===key?{...r,...(field==='matchId'?{matchId:value==='__new'?null:value||null,forceNew:value==='__new',included:value==='__new'}:{[field]:value}),...(field==='ledger'?{included:value!=='ignore',matchId:null,forceNew:false}:{})}:r));});
}

function renderInboxProcessingLog(){
const host=document.createElement('section');host.className='panel bankBody';host.id='inboxProcessingLog';
const labels={attached:'Прикріплено до наявної операції',created:'Створено нову операцію',needs_review:'Потрібна перевірка',duplicate:'Повторний файл',failed:'Помилка'};
const rows=[...(data.inboxProcessingLog||[])].sort((a,b)=>String(b.processedAt||'').localeCompare(String(a.processedAt||'')));
host.innerHTML='<h2>Журнал обробки INBOX</h2><p>Історія обробки документів. Для виписок розподіл і підтвердження показані вище.</p><div class="filters"><select id="inboxLogStatus">'+statementOptions([['','Усі результати'],...Object.entries(labels)],'')+'</select></div><div class="tablewrap"><table><thead><tr><th>Оброблено</th><th>Документ</th><th>Результат</th><th>Операція</th><th>Деталі</th></tr></thead><tbody id="inboxLogRows"></tbody></table></div><p id="inboxLogEmpty"></p>';
$('#view').appendChild(host);
const draw=()=>{const selected=$('#inboxLogStatus').value,shown=rows.filter(r=>!selected||r.status===selected);
$('#inboxLogRows').innerHTML=shown.map(r=>{const record=data.records.find(x=>x.id===r.recordId)||(data.incomeRecords||[]).find(x=>x.id===r.recordId)||(data.insuranceRecords||[]).find(x=>x.id===r.recordId)||(data.taxPaymentRecords||[]).find(x=>x.id===r.recordId);return '<tr><td>'+esc(r.processedAt?new Date(r.processedAt).toLocaleString('uk-UA'):'—')+'</td><td>'+(safeUrl(r.documentUrl)?'<a href="'+esc(safeUrl(r.documentUrl))+'" target="_blank" rel="noopener noreferrer">'+esc(r.fileName||'Документ')+' ↗</a>':esc(r.fileName||'Документ'))+'</td><td>'+esc(labels[r.status]||r.status)+'</td><td>'+(record?'<button type="button" data-log-record="'+esc(record.id)+'">'+esc(displayDate(record.date))+' · '+esc(record.company)+' · '+money(record.amount)+'</button>':r.recordId?'Операцію видалено':'—')+'</td><td>'+esc(r.message||'')+'</td></tr>';}).join('');$('#inboxLogEmpty').textContent=shown.length?'':'Записів ще немає. Наступні обробки INBOX з’являтимуться тут.';
document.querySelectorAll('[data-log-record]').forEach(b=>b.onclick=()=>{const id=b.dataset.logRecord,expense=data.records.find(r=>r.id===id),income=(data.incomeRecords||[]).find(r=>r.id===id),insurance=(data.insuranceRecords||[]).find(r=>r.id===id),tax=(data.taxPaymentRecords||[]).find(r=>r.id===id);if(expense)openRecord(expense);else if(income)openIncomeRecord(income);else if(insurance)openPaymentRecord('insurance',insurance);else if(tax)openPaymentRecord('tax',tax);});};$('#inboxLogStatus').onchange=draw;draw();
}

function openStatementUndo(id){
try{
const plan=SteuerraumFeatures.planStatementUndo(data,id),dialog=document.createElement('dialog');dialog.className='importUndoDialog';
dialog.innerHTML='<div class="dialoghead"><h2>Скасування імпорту</h2><button type="button" data-undo-close>✕</button></div><p>Буде прибрано нових записів: <b>'+plan.removeCount+'</b>. Відновлено попередніх: <b>'+plan.restoreCount+'</b>. Збережено захищених: <b>'+plan.protectedCount+'</b>.</p><p>Файл виписки та документи залишаться в OneDrive. Виписка повернеться до розподілу.</p><div class="tablewrap"><table><thead><tr><th>Операція</th><th>Сума</th><th>Дія</th></tr></thead><tbody>'+plan.steps.filter(s=>s.action!=='none').map(s=>{const r=s.current||s.before||s.after;return '<tr><td>'+esc(r?.date||'')+' · '+esc(r?.company||s.id)+'</td><td>'+money(r?.amount||0)+'</td><td>'+esc(s.action==='remove'?'Прибрати запис':s.action==='restore'?'Відновити попередній стан':'Зберегти: '+s.reason)+'</td></tr>';}).join('')+'</tbody></table></div>'+(plan.protectedCount?'<label><input type="checkbox" data-undo-keep> Зберегти всі захищені записи та скасувати решту імпорту</label>':'')+'<p data-undo-error role="alert"></p><div class="actions"><button type="button" data-undo-close>Назад</button><button type="button" class="danger" data-undo-confirm>Підтвердити скасування</button></div>';
document.body.appendChild(dialog);const close=()=>{dialog.close();dialog.remove();};dialog.querySelectorAll('[data-undo-close]').forEach(b=>b.onclick=close);dialog.addEventListener('close',()=>dialog.remove(),{once:true});
dialog.querySelector('[data-undo-confirm]').onclick=()=>{try{const keepProtected=Boolean(dialog.querySelector('[data-undo-keep]')?.checked);const freshPlan=SteuerraumFeatures.planStatementUndo(data,id);if(JSON.stringify(freshPlan)!==JSON.stringify(plan))throw Error('Дані змінилися. Закрий це вікно й переглянь скасування ще раз.');if(persist(SteuerraumFeatures.undoStatementImport(data,id,{keepProtected}))){close();renderStatementImports();message('Імпорт скасовано. Розподіл доступний для виправлення та повторного внесення.');}}catch(error){dialog.querySelector('[data-undo-error]').textContent=error.message;}};dialog.showModal();
}catch(error){message(error.message,true);}
}

function taxEstimatePanel(){
if(typeof SteuerraumTax==='undefined')return '';
const estimate=SteuerraumTax.estimate(data,year),profile=data.taxEstimateProfile||{},locked=SteuerraumFeatures.closedYear(data,year),settings=SteuerraumTax.getSettings(data,year),supported=Boolean(SteuerraumTax.tariffs[year]);
const settingsForm=supported?'<details class="taxEstimateControls"><summary>Параметри розрахунку</summary><p>Індивідуальний підприємець · індивідуальна декларація · Kirchensteuer 0%. Повний річний тариф застосовується до вже внесених сум, без прогнозу майбутніх доходів.</p><form id="taxEstimateForm"><div class="formgrid"><label>Громада<select name="municipality" '+(locked?'disabled':'')+'>'+statementOptions([['','Обери громаду'],...Object.entries(SteuerraumTax.municipalities).map(([id,m])=>[id,m.name])],profile.municipality)+'</select></label><label>Hebesatz, % (порожньо — ставка громади)<input type="number" name="hebOverride" min="200" max="1000" step=".01" value="'+esc(settings.hebOverride??'')+'" '+(locked?'disabled':'')+'></label><label>Відрахування Basis-Kranken-/Pflegeversicherung, €<input type="number" min="0" step=".01" name="insuranceDeductionCents" value="'+(settings.insuranceDeductionCents/100).toFixed(2)+'" '+(locked?'disabled':'')+'></label><label>Інші підтверджені особисті відрахування, €<input type="number" min="0" step=".01" name="otherDeductionsCents" value="'+(settings.otherDeductionsCents/100).toFixed(2)+'" '+(locked?'disabled':'')+'></label><label>Інші оподатковувані доходи поза реєстром, €<input type="number" min="0" step=".01" name="otherIncomeCents" value="'+(settings.otherIncomeCents/100).toFixed(2)+'" '+(locked?'disabled':'')+'></label><label>Коригування Gewerbeertrag (+/−), €<input type="number" step=".01" name="tradeAdjustmentCents" value="'+(settings.tradeAdjustmentCents/100).toFixed(2)+'" '+(locked?'disabled':'')+'></label></div><p>У Krankenversicherung за цей рік: '+money(SteuerraumFeatures.insuranceSummary(data,year).total)+'. Введи саме суму, дозволену до відрахування за довідкою; вона може відрізнятися від усіх сплачених внесків. Відрахування не змінюють бізнес-витрати.</p>'+(!locked?'<button class="primary" type="submit">Зберегти й перерахувати</button>':'<p>Рік закритий: лише перегляд.</p>')+'<p id="taxEstimateError" role="alert"></p></form></details>':'';
if(!estimate.ready)return '<div class="taxEstimate"><h3>Орієнтовні податки</h3><p>'+esc(estimate.reason)+'</p>'+settingsForm+'</div>';
const e=estimate,rate=n=>(n*100).toFixed(1)+'%',row=(label,value,extra='')=>'<tr><td>'+label+(extra?'<small>'+extra+'</small>':'')+'</td><td class="amount">'+money(value)+'</td></tr>',segments=[['Einkommensteuer',e.incomeTax,'est'],['Gewerbesteuer',e.gewerbe,'trade'],['Soli',e.soli,'soli'],['Після податків',Math.max(0,e.remaining),'net']];
return '<div class="taxEstimate"><h3>Орієнтовний розрахунок · '+esc(year)+'</h3><p>Індивідуальна декларація · без Kirchensteuer · '+esc(e.municipality)+' · Hebesatz '+esc(e.heb)+'%.</p><div class="taxEstimateCards"><div><span>Einkommensteuer після зарахування</span><b>'+money(e.incomeTax)+'</b></div><div><span>Gewerbesteuer</span><b>'+money(e.gewerbe)+'</b></div><div><span>Solidaritätszuschlag</span><b>'+money(e.soli)+'</b></div><div><span>Разом орієнтовно</span><b>'+money(e.totalTax)+'</b></div></div>'+(e.combinedBeforeTax>0?'<div class="taxEstimateBar" role="img" aria-label="Податки '+rate(e.effectiveRate)+' від результату до податків">'+segments.filter(s=>s[1]>0).map(s=>'<span class="'+s[2]+'" style="flex-grow:'+s[1]+'" title="'+esc(s[0])+': '+esc(money(s[1]))+'"></span>').join('')+'</div><div class="taxEstimateLegend">'+segments.map(s=>'<span class="'+s[2]+'">'+esc(s[0])+': '+money(s[1])+'</span>').join('')+'</div>':'')+'<div class="tablewrap"><table class="taxEstimateBreakdown"><tbody>'+row('Прибуток: доходи − бізнес-витрати',e.profit)+row('Інші доходи',e.settings.otherIncomeCents)+row('Особисті відрахування',-e.personalDeductions,'Враховані тільки суми в параметрах; Grundfreibetrag уже включено до тарифу')+row('Орієнтовне zu versteuerndes Einkommen',e.estimatedZve)+row('Einkommensteuer за прогресивним тарифом §32a',e.tariff)+row('Gewerbesteuer окремо',e.gewerbe,'('+money(e.roundedTrade)+' − '+money(2450000)+') × 3,5% × '+e.heb+'%; база не нижче нуля')+row('Зарахування Gewerbesteuer в Einkommensteuer, §35',-e.credit,'Найменше з 4 × Messbetrag, Gewerbesteuer та допустимої частки Einkommensteuer')+row('Einkommensteuer після зарахування',e.incomeTax)+row('Solidaritätszuschlag',e.soli)+row('Разом податків',e.totalTax)+row('Результат після податків',e.remaining,'До особистих витрат і сплати страхування')+'</tbody></table></div><details><summary>Порівняти зі сплаченими податками за '+esc(year)+'</summary><div class="tablewrap"><table><thead><tr><th>Податок</th><th>Оцінка</th><th>Сплачено мінус повернення</th><th>Різниця</th></tr></thead><tbody><tr><td>Einkommensteuer</td><td>'+money(e.incomeTax)+'</td><td>'+money(e.paid.Einkommensteuer)+'</td><td>'+money(e.estBalance)+'</td></tr><tr><td>Gewerbesteuer</td><td>'+money(e.gewerbe)+'</td><td>'+money(e.paid.Gewerbesteuer)+'</td><td>'+money(e.tradeBalance)+'</td></tr></tbody></table></div><p>Лише платежі, віднесені до цього податкового року й конкретного виду податку. Soli у цьому порівнянні не враховано. '+(e.unassignedPayments?'Невизначених платежів: '+e.unassignedPayments+'.':'')+'</p></details>'+settingsForm+'<p class="taxEstimateNote">Це оцінка за поточними даними, а не сума з Steuerbescheid. Особисті пільги, діти, неоподатковувані іноземні доходи, Progressionsvorbehalt, ПДВ та інші спеціальні правила тут не обчислюються. Без введених відрахувань база дорівнює прибутку плюс інші доходи; збитки попередніх років і Sonderausgaben-Pauschbetrag автоматично не віднімаються.</p><details><summary>Ставки й джерела</summary><p>Тарифи перевірені 25.10.2026. <a href="https://www.gesetze-im-internet.de/estg/__32a.html" target="_blank" rel="noopener">EStG §32a</a> · <a href="https://esth.bundesfinanzministerium.de/esth/2025/A-Einkommensteuergesetz/IV-Tarif-31-34b/Paragraf-32a/paragraf-32a.html" target="_blank" rel="noopener">Тариф 2025</a> · <a href="https://www.gesetze-im-internet.de/estg/__35.html" target="_blank" rel="noopener">EStG §35</a> · <a href="https://www.gesetze-im-internet.de/gewstg/__11.html" target="_blank" rel="noopener">GewStG §11</a> · <a href="https://www.gesetze-im-internet.de/solzg_1995/__4.html" target="_blank" rel="noopener">SolzG</a> · <a href="'+esc(SteuerraumTax.municipalities[profile.municipality]?.source||'https://www.frankfurt-main.ihk.de/')+'" target="_blank" rel="noopener">Hebesatz</a>.</p></details></div>';
}
function bindTaxEstimate(){const form=$('#taxEstimateForm');if(!form)return;form.onsubmit=event=>{event.preventDefault();try{const input={};for(const name of ['insuranceDeductionCents','otherDeductionsCents','otherIncomeCents','tradeAdjustmentCents'])input[name]=Math.round(Number(form.elements[name].value)*100);if(form.elements.hebOverride.value!=='')input.hebOverride=Number(form.elements.hebOverride.value);const profile={...(data.taxEstimateProfile||{}),assessment:'single',churchRate:0,trade:true,municipality:form.elements.municipality.value};if(!profile.municipality&&input.hebOverride==null)throw Error('Обери громаду або вкажи Hebesatz.');const next=SteuerraumTax.saveSettings({...data,taxEstimateProfile:profile},year,input);if(persist(next))render();}catch(error){$('#taxEstimateError').textContent=error.message;}};}

render();